"""Complete the grade-eight enrichment section, printed page 223 (2023 edition)."""
from math import dist, sqrt
from chord_followup import chord, circum
from circle_bisectors import frame
from circle_lessons import circle_each, solution
from circle_theorems import add_circle
from midpoint_lessons import coordinates, edges, foot, mid


def item(n,statement,answer,hint,steps,frames,check,part=None):
    return solution(n,statement,answer,hint,steps,frames,check,part=part,page=223)


def tangents_and_chords():
    def data(internal):
        radius,small,d=3,1,6
        offset=radius+small if internal else radius-small
        nx=offset/d;ny=sqrt(1-nx**2)
        sign=-1 if internal else 1
        return dict(O=(0,0),Q=(d,0),U=(0,-radius),V=(d,-small),T=(offset*nx,offset*ny),
                    X=(radius*nx,radius*ny),Y=(d+sign*small*nx,sign*small*ny))
    e,s=data(False),data(True)
    one=item(920,'Даны две окружности. Построй все прямые, касающиеся обеих, и выясни, при каких положениях окружностей они существуют.',
        'Для внешней касательной найди направление по вспомогательной окружности радиуса R−r и для внутренней — радиуса R+r. Расстояние d между центрами определяет, сколько таких прямых можно провести.',
        'При параллельном переносе касательной на расстояние малого радиуса она проходит через центр меньшей окружности. Как тогда меняется расстояние от неё до большего центра?',
        [('Как задаётся внешняя касательная?', 'Пусть O и Q — центры окружностей радиусов R≥r. При R>r построй вокруг O окружность радиуса R−r и из Q проведи к ней касательные. Для каждой точки касания T возьми направление OT. От O и Q отложи в этом направлении радиусы R и r до X и Y. Прямая через X, перпендикулярная OT, проходит через Y и касается обеих окружностей.',
          'Касательную через Q к вспомогательной окружности строят пересечением с окружностью диаметра OQ. При касании в самом Q направление касательной перпендикулярно OQ.'),
         ('Что меняется для внутренней касательной?', 'Теперь центры должны лежать по разные стороны искомой прямой. Построй вспомогательную окружность радиуса R+r. Для касательной из Q снова отложи OX=R по направлению OT, а QY=r — против него. Перпендикуляр к OT через X служит общей касательной и тогда, когда X и Y совпадают.',
          'Радиусы, проведённые в точки касания, параллельны. Их направленные расстояния до внутренней касательной имеют разные знаки.'),
         ('Сколько решений дают оба построения?', 'При d>R+r получаются 4 прямые, при d=R+r — 3. Если R−r<d<R+r, остаются 2 внешние. При d=R−r>0 есть 1, при d<R−r решений нет. Для R=r и разных центров две внешние касательные параллельны OQ на расстоянии R. При общем центре и неравных радиусах общей касательной нет, у совпадающих окружностей их бесконечно много.',
          'Из точки вне окружности к ней проводят две касательные, на окружности — одну, внутри — ни одной. Каждая общая касательная проходит через описанный перенос, поэтому перечень полный.')],
        [frame(e,'OQUV',[('O','Q')]),frame(e,'OQUVTXY',[('O','Q'),('Q','T'),('O','X'),('Q','Y'),('X','Y')]),
         frame(s,'OQUVTXY',[('O','Q'),('Q','T'),('O','T'),('Q','Y'),('X','Y')]),
         frame(e,'OQUVTXY',[('O','X'),('Q','Y'),('X','Y')])],
        (3,'У двух окружностей R=5, r=2 и d=7. Сколько общих касательных?', ['3'],'При внешнем касании две внешние касательные различны, а внутренние совпали.'))
    circle_each(one,[('O','U'),('Q','V')])
    for j in [1,2]:add_circle(one,j,'O','T')

    p=dict(O=(0,0),M=(2,7),A=(-4,3),B=(4,3),H=(0,3),K=(2,3),U=(5,0))
    two=item(921,'В окружности с центром O нужна хорда заданной положительной длины L. Её прямая должна проходить на заданном расстоянии b от точки M. Построй все подходящие прямые.',
        'Найди a=√(R²−(L/2)²). Искомая прямая должна находиться на расстоянии a от O и b от M. Это задача об общих касательных двух вспомогательных окружностей.',
        'Начни с одного условия: на каком расстоянии от центра лежит хорда данной длины?',
        [('Как построить расстояние a?', 'Пусть R — радиус. Если L>2R, такой хорды нет. При 0<L≤2R построй прямоугольный треугольник с гипотенузой R и катетом L/2. Его второй катет a — расстояние от O до прямой хорды, потому что перпендикуляр к хорде делит её пополам.',
          'Из равенства R²=a²+(L/2)² следует единственное неотрицательное значение a.'),
         ('Какие касательные выбрать?', 'При a>0 и b>0 построй окружности с центрами O, M и радиусами a, b. Все их общие касательные из №920 дают искомые прямые. Их пересечения с исходной окружностью — концы нужных хорд.',
          'Касание равносильно равенству расстояния от центра до прямой заданному радиусу. Если вспомогательные окружности совпали, годятся все их касательные.'),
         ('Что делать, когда одно из расстояний нулевое?', 'При a=0 прямая обязана проходить через O: проведи из O касательные к окружности центра M радиуса b, если b>0. При b=0 поступи наоборот. Если оба нули и O≠M, единственная прямая — OM; при O=M годятся все прямые через общий центр. Полученную прямую проверь по обоим исходным расстояниям.',
          'Когда касательная из заданной точки к окружности не существует, соответствующее условие не даёт решений.')],
        [frame(p,'OMABHU',[('A','B'),('O','A'),('O','H')]),frame(p,'OMABHU',[('A','B'),('O','A'),('O','H')],('OHA',)),
         frame(p,'OMABHKU',[('A','B'),('O','H'),('M','K')]),frame(p,'OMABHKU',[('A','B'),('O','H'),('M','K')])],
        (1,'R=5, L=8. Чему равно расстояние от центра до прямой хорды?', ['3'],'У прямоугольного треугольника гипотенуза 5, один катет 4.'))
    circle_each(two,[('O','U')])
    for j in [2,3]:add_circle(two,j,'O','H');add_circle(two,j,'M','K')

    o=(0,0);p0=(3,0);t=(1,.45)
    h=foot(o,p0,(p0[0]+t[0],t[1]));unit=coordinates((0,0),t,1/dist((0,0),t));half=sqrt(25-dist(o,h)**2)
    a=coordinates(h,(h[0]+unit[0],h[1]+unit[1]),half)
    b=coordinates(h,(h[0]+unit[0],h[1]+unit[1]),-half)
    p=dict(O=o,P=p0,A=a,B=b,H=h,X=(3,4),Y=(3,-4))
    three=item(922,'Внутри окружности дана точка P. Построй кратчайшую из всех хорд, проходящих через P. Объясни, всегда ли она единственная.',
        'При P≠O искомая хорда перпендикулярна OP в P. Её длина равна 2√(R²−OP²). Если P=O, все подходящие хорды являются диаметрами.',
        'Для хорды AB сравни OP с расстоянием OH до прямой AB. Как длина хорды меняется при увеличении OH?',
        [('Как выразить длину произвольной хорды?', 'Опусти OH на хорду AB через P. H делит AB пополам. Из прямоугольного треугольника OHA следует AB=2√(R²−OH²); если H=O, это диаметр. В пределах 0≤OH<R большему OH соответствует меньшая хорда.',
          'R постоянно, поэтому при увеличении вычитаемого OH² уменьшается квадрат полухорды.'),
         ('Какое OH может быть самым большим?', 'Длина перпендикуляра OH не больше расстояния OP до любой точки той же прямой. Для P≠O равенство возможно ровно при H=P. Проведи через P перпендикуляр к OP и отметь точки X,Y его пересечения с окружностью.',
          'В прямоугольном треугольнике OHP гипотенуза OP больше катета OH, пока H не совпадает с P.'),
         ('Почему других минимальных хорд нет?', 'Для любой другой прямой через P имеем OH<OP, значит построенная XY строго короче её хорды. Если P=O, расстояние до любой такой прямой равно нулю; все хорды через центр имеют одинаковую длину 2R.',
          'P внутри круга, поэтому построенный перпендикуляр действительно даёт две различные точки пересечения.')],
        [frame(p,'OPAB',[('A','B'),('O','P')]),frame(p,'OPABH',[('A','B'),('O','A'),('O','H')],('OHA',)),
         frame(p,'OPABHXY',[('A','B'),('O','H'),('O','P'),('X','Y')]),frame(p,'OPXY',[('O','P'),('X','Y'),('O','X')],('OPX',))],
        (3,'Если R=5 и OP=3, чему равна полная длина минимальной хорды?', ['8'],'Сначала найди половину хорды как катет; затем удвой её.'))
    for j,k in enumerate('AAAX'):add_circle(three,j,'O',k)
    return [one,two,three]


def triangle_constructions():
    a,b,c=(2,4),(0,0),(8,0);o=circum(a,b,c);k=(6,4);h=(2,0)
    p=dict(A=a,B=b,C=c,K=k,O=o,H=h,U=(0,4),V=(8,4),M=mid(b,c))
    abc=edges('ABC')
    four_a=item(923,'Дана сторона BC длины a, противолежащий угол A величины α и высота h из A к прямой BC. Построй треугольник и проверь, при каких данных он существует.',
        'Вершина A должна одновременно лежать на прямой, параллельной BC на расстоянии h, и на дуге, с которой BC виден под углом α. Над BC решения существуют при 0<h≤(a/2)cot(α/2).',
        'Построй отдельно два геометрических места для вершины A: одно отвечает за высоту, другое за угол.',
        [('Где можно искать вершину?', 'Начерти BC=a. При a>0, h>0 и 0°<α<180° проведи две прямые, параллельные BC на расстоянии h. Нижние решения будут отражениями верхних. Пока рассматривай верхнюю прямую.',
          'Высота есть расстояние до всей прямой BC, поэтому её основание не обязано находиться на самом отрезке.'),
         ('Как построить подходящую дугу?', 'У B проведи касательную, образующую с BC угол α с выбранной стороны. Центр окружности лежит на перпендикуляре к касательной в B и на серединном перпендикуляре к BC. Для второго положения касательной получается отражённая окружность. Выбери дугу, чьи точки над BC видят BC под углом именно α, и пересеки её с проведённой прямой.',
          'Угол между касательной и хордой равен вписанному углу соответствующего сегмента. При α=90° нужная окружность имеет диаметр BC.'),
         ('Как отличить два решения от одного или ни одного?', 'Верхняя точка дуги лежит над серединой BC. Получается равнобедренный треугольник с углом α при вершине; его высота h₀=(a/2)cot(α/2). При 0<h<h₀ сверху две точки, симметричные относительно серединного перпендикуляра. При h=h₀ одна, при h>h₀ ни одной. На нижней стороне картина зеркальна.',
          'Симметричные решения различаются положением на построенном чертеже, получающиеся треугольники равны.')],
        [frame(p,'ABCH',abc+[('A','H')]),frame(p,'BCUVH',[('B','C'),('U','V'),('U','B')]),
         frame(p,'ABCKOUV',abc+[('U','V'),('B','K'),('K','C')]),frame(p,'ABCKOUVH',abc+[('U','V'),('A','H'),('B','K'),('K','C')])],
        (3,'BC=10, угол A прямой, высота равна 5. Сколько положений A над BC?', ['1'],'Полуокружность радиуса 5 лишь касается параллельной прямой на высоте 5.'),part='а')
    for j in [2,3]:add_circle(four_a,j,'O','B')
    s=(dist(a,b)+dist(b,c)+dist(c,a))/2
    i=tuple((dist(b,c)*a[j]+dist(c,a)*b[j]+dist(a,b)*c[j])/(2*s) for j in (0,1))
    p.update(I=i,T=foot(i,a,b))
    four_b=item(923,'Даны угол A=α, высота h из A и периметр p треугольника. Построй треугольник без предварительно заданной стороны.',
        'Сначала построй отрезок q=h·cot(α/2). По данным определяется основание a=(p/2)·p/(p+q). После его построения применима задача №923а. Проверь заданный периметр.',
        'У вписанной окружности радиус r связан с площадью, а две касательные из A имеют длину s−a, где s — полупериметр.',
        [('Как исключить неизвестную площадь?', 'Обозначь s=p/2, a=BC, I — центр вписанной окружности, T — точку касания AB. Площадь равна ah/2 и одновременно rs. Значит r=ah/(2s). Из равных касательных AT=s−a, а из прямоугольного треугольника AIT получаем AT=r·cot(α/2).',
          'AI — биссектриса угла A, IT перпендикулярна AB. Полупериметр минус BC равен общей длине касательных именно из A.'),
         ('Как циркулем и линейкой получить сторону a?', 'Из s−a=(ah/(2s))cot(α/2) следует a=(p/2)·p/(p+q), где q=h·cot(α/2). Построй q как прилежащий катет прямоугольного треугольника с противоположным катетом h и углом α/2. Отрезок (p/2) в отношении p:(p+q) построй с помощью подобных треугольников.',
          'При умножении обеих частей на 2s получится 2s²=a(2s+q), а 2s=p.'),
         ('Как завершить построение и проверить его?', 'Построй BC найденной длины. Найди A по стороне, углу и высоте способом №923а. Для каждого полученного треугольника сравни сумму трёх сторон с p. Условие h≤(a/2)cot(α/2) проверяет, пересечётся ли нужная дуга с параллелью; p,h должны быть положительными, а угол — строго между 0° и 180°.',
          'Любое решение обязано иметь найденную сторону a; проверка исходных трёх данных завершает обратное рассуждение.')],
        [frame(p,'ABCH',abc+[('A','H')]),frame(p,'ABCHIT',abc+[('A','I'),('I','T'),('A','H')]),
         frame(p,'ABCHIT',abc+[('A','I'),('I','T'),('A','H')],('AIT',)),frame(p,'ABCHOUV',abc+[('A','H'),('U','V')])],
        (2,'В модели с p=12 построен q=2,4. Найди a по выведенной формуле.', ['5'],'Вычисли (12/2)·12/(12+2,4).'),part='б')
    for j in [1,2]:add_circle(four_b,j,'I','T')
    add_circle(four_b,3,'O','B')

    y,z,x=(-4,-3),(4,-3),(3,4);o=(0,0);a=(3,-4);b=(0,-5);t=(0,-3);h=(3,-3)
    m=chord(o,x,(t[0]-x[0],t[1]-x[1]))
    p=dict(A=a,B=b,M=m,X=x,Y=y,Z=z,O=o,T=t,H=h)
    five=item(924,'На данной описанной окружности отмечены A, B, M — вторые точки пересечения с прямыми высоты, биссектрисы и медианы, проведённых из одной вершины X. Восстанови вершины треугольника.',
        'Прямая OB задаёт направление высоты. Через A параллельно OB восстанавливается X. Пересечение XM с OB определяет середину T стороны YZ; перпендикуляр к OB через T даёт концы стороны.',
        'Вспомни смысл второй точки пересечения биссектрисы с окружностью. Что можно узнать о противоположной стороне, пока её концов нет на рисунке?',
        [('Как восстановить общую вершину X?', 'B — середина дуги YZ без X, поэтому OB перпендикулярна хорде YZ. Высота из X тоже перпендикулярна YZ. Проведи через A прямую параллельно OB и возьми её второе пересечение с окружностью за X. Если она касается окружности или X совпадает с другой заданной второй точкой, построение с тремя различными вторыми точками невозможно.',
          'Биссектриса из точки окружности делит стягиваемую ею дугу пополам.'),
         ('Как узнать положение самой хорды YZ?', 'Середина любой хорды, перпендикулярной OB, лежит на прямой OB. С другой стороны, середина T стороны YZ лежит на медиане XM. Значит T — пересечение прямых XM и OB. Проведи через T перпендикуляр к OB: его пересечения с окружностью обозначь Y и Z.',
          'При различных вторых точках медиана и прямая OB не могут совпасть или быть параллельны: иначе она совпадала бы с высотой из X и имела ту же вторую точку.'),
         ('Какие проверки нужны после построения?', 'T должен быть строго внутри круга, Y и Z — различны и не равны X. Убедись, что B лежит на дуге YZ без X: только тогда XB — внутренняя биссектриса. Проверь также направления XA и XM. При этих условиях треугольник построен, а обмен Y и Z лишь переименовывает вершины.',
          'Проверка выбирает внутреннюю биссектрису из двух прямых, которые делят углы между сторонами пополам.')],
        [frame(p,'ABMO',[('O','B')]),frame(p,'ABMOX',[('O','B'),('A','X')]),
         frame(p,'ABMOXYZT',edges('XYZ')+[('X','M'),('B','O'),('T','O')]),
         frame(p,'ABMOXYZTH',edges('XYZ')+[('X','M'),('A','X'),('X','B'),('O','B')])],
        (2,'В проверочном чертеже радиус равен 5, OT=3. Найди длину всей хорды YZ.', ['8'],'Половина хорды равна √(5²−3²).'))
    circle_each(five,[('O','A')])
    # P, Q, R are the three given feet. Four choices of signs give I and its three excentres.
    v=[(0,4),(-3,0),(4,0)]
    sides=[dist(v[1],v[2]),dist(v[0],v[2]),dist(v[0],v[1])]
    def center(signs):
        w=[s*k for s,k in zip(sides,signs)]
        return tuple(sum(a*point[j] for a,point in zip(w,v))/sum(w) for j in (0,1))
    p=dict(P=v[0],Q=v[1],R=v[2],I=center((1,1,1)),U=center((-1,1,1)),V=center((1,-1,1)),W=center((1,1,-1)))
    tri=edges('PQR')
    proof={**p,'A':p['U'],'B':p['V'],'C':p['W'],'H':p['I'],'K':mid(p['W'],p['I']),'L':mid(p['V'],p['I'])}
    six=item(925,'Даны три неколлинеарные точки P, Q и R. Построй все треугольники с этими тремя основаниями высот. Сколько разных треугольников получится без учёта обозначений вершин?',
        'Построй центр вписанной и три центра вневписанных окружностей треугольника PQR. Выбирая любые три из четырёх центров в качестве вершин, получишь ровно четыре решения. Оставшийся центр — ортоцентр выбранного треугольника.',
        'Каждая сторона искомого треугольника и высота к ней образуют в заданной точке пару перпендикулярных прямых. Ищи их среди внутренних и внешних биссектрис PQR.',
        [('Почему нужные прямые делят углы ортотреугольника пополам?', 'Для любого решения назовём A вершиной, высота из которой попадает в P на BC, Q и R — основания высот из B и C. Пусть H — ортоцентр. Четвёрки C,Q,H,P и B,R,H,P лежат на окружностях по прямым углам. По вписанным углам ∠QPH=∠QCH и ∠HPR=∠HBR по модулю 180°. Так как CH перпендикулярна AB, а BH перпендикулярна AC, последние углы равны. Поэтому PH и перпендикулярная ей BC образуют пару биссектрис угла между PQ и PR. У Q и R верно то же.',
          'Сравнение направлений по модулю 180° включает случай, когда основания высот лежат на продолжениях сторон. Для прямоугольного решения два основания совпали бы — это исключено данными.'),
         ('Какие четыре точки дают все пересечения?', 'Построй у каждой вершины PQR внутреннюю и внешнюю биссектрисы. I — пересечение внутренних. U, V, W — центры вневписанных окружностей напротив P, Q, R. У P одна биссектриса есть IU, другая VW; у Q — IV и UW; у R — IW и UV. Это ровно четыре точки, равноудалённые от трёх прямых сторон PQR. Значит и три вершины любого решения, и H входят в эту четвёрку.',
          'Две биссектрисы пары пересекающихся прямых описывают все точки, равноудалённые от этих прямых. Третье условие расстояний даёт центр вписанной или одной из трёх вневписанных окружностей.'),
         ('Почему каждый выбор трёх действительно подходит?', 'Для треугольника UVW прямые UI и VW пересекаются под прямым углом в P; VI и UW — в Q; WI и UV — в R. Поэтому I — его ортоцентр, а P,Q,R — основания высот. Если вместо I оставить за пределами треугольника любой из U,V,W, те же три перпендикулярные пары останутся теми же высотами и сторонами с поменявшимися ролями. Выбор оставленного центра даёт четыре разных треугольника.',
          'Все четыре центра различны для невырожденного PQR. Любые три образуют невырожденный треугольник: на одной биссектрисе лежат ровно два из четырёх центров.')],
        [frame(p,'PQR',tri),frame(proof,'PQRABCHKL',tri+[('A','P'),('B','C'),('C','H'),('B','H')]),
         frame(p,'PQRIVUW',tri+[('I','U'),('I','V'),('I','W')]+edges('UVW')),
         frame(p,'PQRIVUW',edges('UVW')+[('I','U'),('I','V'),('I','W')],('UVW',))],
        (3,'Если оставленный центр I уже дал один треугольник, сколько других выборов оставленного центра ещё есть?', ['3'],'Из четырёх центров один уже использован в роли ортоцентра.'))
    add_circle(six,1,'K','C');add_circle(six,1,'L','B')
    return [four_a,four_b,five,six]
